// Links a walkthrough's generated PDFs into its page's frontmatter (docs/scope.md "Printable
// guides"; AGENTS.md ownership note for this milestone: "add a 'Download PDF' link in the page
// frontmatter (`pdf:` key)"). Deliberately a small, targeted patch of the two engine-owned
// `pdf`/`pdfCard` lines rather than a full page rebuild through pages/markers.ts: the PDF stage
// runs after the pages stage (build-plan.md M12), so by the time PDFs exist the page's
// frontmatter block has already been written for this run. Frontmatter is always fully
// regenerated by the pages module on every build (pages/markers.ts: "engine-owned keys... always
// overwritten") — inserting two more engine-owned keys here is the same contract, just applied
// without re-running the (expensive, screenshot-annotating) page build.
import { existsSync, readFileSync, writeFileSync } from "node:fs";

const FRONTMATTER_RE = /^(---\r?\n)([\s\S]*?)(\r?\n---\r?\n?)/;

function yamlString(s: string): string {
  return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}

export interface PdfFrontmatterLinks {
  /** Path to the walkthrough's `<id>.pdf`, relative to the page's directory. */
  pdf?: string;
  /** Path to the walkthrough's `<id>.card.pdf`, relative to the page's directory. */
  pdfCard?: string;
}

/** Rewrites (or inserts) the `pdf:`/`pdfCard:` lines in `indexFile`'s frontmatter block to
 * `links`. No-op (file untouched) if the file has no frontmatter, or the lines already match —
 * so this never bumps the file's mtime on an unchanged build. */
export function setPdfFrontmatter(indexFile: string, links: PdfFrontmatterLinks): void {
  if (!existsSync(indexFile)) return;
  const raw = readFileSync(indexFile, "utf8");
  const match = FRONTMATTER_RE.exec(raw);
  if (!match) return;

  const bodyLines = match[2].split(/\r?\n/).filter((l) => !/^pdf:\s|^pdfCard:\s/.test(l));
  if (links.pdf) bodyLines.push(`pdf: ${yamlString(links.pdf)}`);
  if (links.pdfCard) bodyLines.push(`pdfCard: ${yamlString(links.pdfCard)}`);

  const newFrontmatter = `${match[1]}${bodyLines.join("\n")}${match[3]}`;
  if (newFrontmatter === match[0]) return;
  writeFileSync(indexFile, newFrontmatter + raw.slice(match[0].length));
}
